package com.MITProjectService.bot.dao.jpaRepos.specification;import com.MITProjectService.bot.domain.Payment;import com.MITProjectService.bot.request.PaymentRequest;import jakarta.persistence.criteria.Predicate;import org.springframework.data.jpa.domain.Specification;import org.springframework.stereotype.Service;@Servicepublic class PaymentFilterSpecification {    public static Specification<Payment> filter(PaymentRequest paymentRequest) {        return (root, query, criteriaBuilder) -> {            Predicate predicate = criteriaBuilder.conjunction();            if (paymentRequest.getOrderId() != null) {                predicate = criteriaBuilder.and(predicate,                        criteriaBuilder.equal(root.get("paymentOrderId"), paymentRequest.getOrderId()));            }            if (paymentRequest.getBookingId() != null) {                predicate = criteriaBuilder.and(predicate,                        criteriaBuilder.equal(root.get("booking").get("id"), paymentRequest.getBookingId()));            }            if (paymentRequest.getPaymentStatus() != null) {                predicate = criteriaBuilder.and(predicate,                        criteriaBuilder.equal(root.get("paymentStatus"), paymentRequest.getPaymentStatus()));            }            return predicate;        };    }}